application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #526078;
  --surface: #ffffff;
  --background: #f3f6fb;
  --border: #c9d2e2;
  --accent: #2457c5;
  --accent-dark: #173f96;
  --danger: #a32929;
  --completed: #667085;
}

body {
  margin: 0;
  min-width: 16rem;
  background: var(--background);
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

.app-shell {
  width: min(100% - 2rem, 46rem);
  margin: 0 auto;
  padding: 3rem 0 4rem;
}

.page-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .4rem;
  color: var(--accent-dark);
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}

h1, h2 {
  margin-top: 0;
  line-height: 1.2;
}

h1 {
  margin-bottom: .6rem;
  font-size: clamp(2rem, 6vw, 3rem);
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.intro {
  max-width: 35rem;
  margin: 0;
  color: var(--muted);
}

.todo-panel,
.tasks-section {
  padding: 1.5rem;
  border: 1px solid var(--border);
  border-radius: .75rem;
  background: var(--surface);
  box-shadow: 0 .25rem 1rem rgba(23, 32, 51, .06);
}

.tasks-section {
  margin-top: 1.25rem;
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-weight: 700;
}

input[type="text"] {
  width: 100%;
  min-height: 2.75rem;
  padding: .65rem .75rem;
  border: 1px solid #8996aa;
  border-radius: .4rem;
  color: var(--ink);
  background: #fff;
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: .6rem 1rem;
  border: 0;
  border-radius: .4rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid #f0a500;
  outline-offset: 2px;
}

.form-message {
  min-height: 1.5rem;
  margin: .5rem 0 0;
  color: var(--danger);
  font-weight: 600;
}

.section-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.section-heading h2 {
  margin-bottom: 0;
}

.count {
  margin: 0;
  color: var(--muted);
  font-weight: 700;
  white-space: nowrap;
}

.task-list {
  display: grid;
  gap: .7rem;
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .8rem;
  border: 1px solid var(--border);
  border-radius: .5rem;
}

.task-toggle {
  flex: 1;
  min-height: 2.25rem;
  padding: .35rem .5rem;
  border: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  font-weight: 600;
}

.task-toggle:hover {
  background: #edf2fc;
  color: var(--ink);
}

.task-item[data-completed="true"] .task-toggle {
  color: var(--completed);
  text-decoration: line-through;
}

.delete-button {
  background: #fff;
  color: var(--danger);
  border: 1px solid #d58b8b;
}

.delete-button:hover {
  background: #fff1f1;
  color: #7d1d1d;
}

.empty-state {
  margin: 1.25rem 0 0;
  color: var(--muted);
}

@media (max-width:  thirtyrem) {
  .input-row,
  .section-heading {
    align-items: stretch;
    flex-direction: column;
  }

  .input-row button {
    width: 100%;
  }
}

@media (max-width: 30rem) {
  .app-shell {
    padding-top: 2rem;
  }

  .todo-panel,
  .tasks-section {
    padding: 1rem;
  }

  .task-item {
    align-items: stretch;
    flex-wrap: wrap;
  }

  .task-toggle {
    min-width: 0;
  }
}

