const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('[data-testid="task-input"]');
const taskError = document.querySelector('#task-error');
const taskList = document.querySelector('[data-testid="task-list"]');
const incompleteCount = document.querySelector('[data-testid="incomplete-count"]');
const emptyState = document.querySelector('#empty-state');

let tasks = [];
let nextTaskId = 1;

function updateSummary() {
  const incompleteTasks = tasks.filter((task) => !task.completed).length;
  incompleteCount.textContent = String(incompleteTasks);
  emptyState.hidden = tasks.length > 0;
}

function createTaskElement(task) {
  const item = document.createElement('li');
  item.className = 'task-item';
  item.dataset.testid = 'task';
  item.dataset.completed = String(task.completed);

  const toggleButton = document.createElement('button');
  toggleButton.type = 'button';
  toggleButton.className = 'task-toggle';
  toggleButton.dataset.testid = 'task-complete';
  toggleButton.textContent = task.text;
  toggleButton.setAttribute('aria-label', `${task.completed ? 'Mark incomplete' : 'Mark complete'}: ${task.text}`);
  toggleButton.addEventListener('click', () => toggleTask(task.id));

  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'delete-button';
  deleteButton.dataset.testid = 'task-delete';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', `Delete task: ${task.text}`);
  deleteButton.addEventListener('click', () => deleteTask(task.id));

  item.append(toggleButton, deleteButton);
  return item;
}

function renderTasks() {
  taskList.replaceChildren(...tasks.map(createTaskElement));
  updateSummary();
}

function addTask(text) {
  tasks.push({ id: nextTaskId, text, completed: false });
  nextTaskId += 1;
  renderTasks();
}

function toggleTask(taskId) {
  tasks = tasks.map((task) => task.id === taskId ? { ...task, completed: !task.completed } : task);
  renderTasks();
}

function deleteTask(taskId) {
  tasks = tasks.filter((task) => task.id !== taskId);
  renderTasks();
}

function handleTaskSubmit(event) {
  event.preventDefault();
  const text = taskInput.value.trim();
  if (!text) {
    taskError.textContent = 'Enter a task before adding it.';
    taskInput.focus();
    return;
  }

  taskError.textContent = '';
  addTask(text);
  taskInput.value = '';
  taskInput.focus();
}

taskForm.addEventListener('submit', handleTaskSubmit);
taskInput.addEventListener('input', () => {
  if (taskInput.value.trim()) taskError.textContent = '';
});

renderTasks();
